```java
// OK: static, parameterless, run once
try (Statement st = con.createStatement()) {
    st.execute("CREATE TABLE audit (id INT PRIMARY KEY, msg VARCHAR(200))");
}

// NOT OK as a Statement — has input + may repeat:
// use a PreparedStatement instead
try (PreparedStatement ps = con.prepareStatement(
        "INSERT INTO audit (id, msg) VALUES (?, ?)")) {
    ps.setInt(1, 1); ps.setString(2, "started");
    ps.executeUpdate();
}
```

```java
try (Statement st = con.createStatement()) {
    for (int i = 0; i < 10_000; i++) {
        // the DB parses + plans this SQL 10,000 times
        st.executeUpdate("INSERT INTO logs (msg) VALUES ('row " + i + "')");
    }
}
```

```java
try (PreparedStatement ps =
        con.prepareStatement("INSERT INTO logs (msg) VALUES (?)")) {
    for (int i = 0; i < 10_000; i++) {
        ps.setString(1, "row " + i);
        ps.addBatch();                 // queue
    }
    ps.executeBatch();                 // one round-trip, plan reused
}
```

*Parsed and planned once, parameters rebound each iteration, and batched into far fewer round-trips.*

```java
// proc: get_user_count(IN city VARCHAR, OUT total INT)
try (CallableStatement cs = con.prepareCall("{call get_user_count(?, ?)}")) {
    cs.setString(1, "Pune");                          // IN
    cs.registerOutParameter(2, java.sql.Types.INTEGER); // OUT — register first!
    cs.execute();
    int total = cs.getInt(2);                          // read OUT after execute
    System.out.println("users in Pune: " + total);
}
```

```java
// prepare(): parse + validate + plan happen here, once
try (PreparedStatement ps =
        con.prepareStatement("SELECT * FROM orders WHERE customer_id = ?")) {
    for (int id : customerIds) {     // many executions
        ps.setInt(1, id);            // just bind...
        try (ResultSet rs = ps.executeQuery()) {  // ...and run the cached plan
            while (rs.next()) { /* ... */ }
        }
    }
}
// the SQL is parsed and planned once, then reused for every id
```

```java
try (CallableStatement cs = con.prepareCall("{call orders_by_city(?, ?)}")) {
    cs.setString(1, "Pune");                            // IN
    cs.registerOutParameter(2, java.sql.Types.INTEGER);  // OUT total
    boolean hasRs = cs.execute();
    if (hasRs) {                                         // optional ResultSet
        try (ResultSet rs = cs.getResultSet()) {
            while (rs.next()) System.out.println(rs.getString("id"));
        }
    }
    int total = cs.getInt(2);                            // OUT after execute
    System.out.println("total: " + total);
}
